import math
import unittest
from fractions import Fraction

from solution import render_piecework_badge


class PieceworkBadgeTests(unittest.TestCase):
    def test_normal_result_is_returned_with_exact_format(self):
        self.assertEqual(
            render_piecework_badge(42, 8, 12.5),
            "WORKER = 42\nPAY = CR 100.00",
        )

    def test_rounding_and_fraction_rate(self):
        self.assertEqual(
            render_piecework_badge(7, 3, Fraction(10, 3)),
            "WORKER = 7\nPAY = CR 10.00",
        )

    def test_zero_values_are_valid(self):
        self.assertEqual(
            render_piecework_badge(0, 0, 0),
            "WORKER = 0\nPAY = CR 0.00",
        )
        self.assertEqual(
            render_piecework_badge(0, 5, 0.0),
            "WORKER = 0\nPAY = CR 0.00",
        )

    def test_invalid_staff_code_types(self):
        for value in [True, False, 1.0, "1", None]:
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    render_piecework_badge(value, 1, 1)

    def test_invalid_completed_units_types(self):
        for value in [True, False, 1.0, "1", None]:
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    render_piecework_badge(1, value, 1)

    def test_invalid_rate_types(self):
        for value in [True, False, "1", 1 + 0j, None]:
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    render_piecework_badge(1, 1, value)

    def test_negative_values_raise_value_error(self):
        for args in [(-1, 1, 1), (1, -1, 1), (1, 1, -0.01)]:
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    render_piecework_badge(*args)

    def test_non_finite_rates_raise_value_error(self):
        for rate in [math.inf, -math.inf, math.nan]:
            with self.subTest(rate=rate):
                with self.assertRaises(ValueError):
                    render_piecework_badge(1, 1, rate)


if __name__ == "__main__":
    unittest.main()

